// Version A: single interface
interface Serializer {
  serialize(obj: any): string;
}
class JsonSerializer implements Serializer {
  serialize(obj: any) { return JSON.stringify(obj); }
}
class XmlSerializer implements Serializer {
  serialize(obj: any) { /* produce XML string */ return '<xml/>'; }
}

// Version B: differing APIs and local adapters
class JsonLegacy { toJson(obj: any) { return JSON.stringify(obj); } }
class XmlLegacy { serializeToXml(obj: any) { return '<xml/>'; } }
